import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { x as xIcon } from "../../../icons/index";
import { isPreventScrollSupported } from "../../utils/browser";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {
	handleEndSentinelFocus,
	handleStartSentinelFocus,
} from "../../utils/keyboardHelper";
import Modal from "../../utils/modal";
import { lockBodyScrolling, unlockBodyScrolling } from "../../utils/scroll";
import { hasSlot } from "../../utils/slot";

const hasPreventScroll = isPreventScrollSupported();

let id = 0;

/**
 * @since 0.0.10
 * @status stable
 *
 * @data-testid close-button - The default close button rendered in the drawer header.
 *
 * @slot - The drawer's content.
 * @slot label - The drawer's label. Alternatively, you can use the label prop.
 * @slot title - The drawer's level 2 heading. Use this instead of the label slot when providing a description.
 * @slot description - Supporting text that describes the drawer.
 * @slot footer - The drawer's footer, usually one or more buttons representing various options.
 *
 * @part base - The component's base wrapper.
 * @part overlay - The overlay.
 * @part panel - The drawer panel (where the drawer and its content is rendered).
 * @part header - The drawer header.
 * @part title - The drawer title.
 * @part description - The drawer description.
 * @part close-button - The close button.
 * @part body - The drawer body.
 * @part footer - The drawer footer.
 * @part closer - The drawer closer X.
 */
@Component({
	tag: "hbr-drawer",
	styleUrl: "drawer.scss",
	shadow: true,
})
export class Drawer {
	componentId = `drawer-${++id}`;
	drawer: HTMLElement;
	modal: Modal;
	panel: HTMLElement;
	bodyRef: HTMLElement;
	willShow = false;
	willHide = false;
	// TODO : remove support for footer padding in v2.0 and remove this logic.
	buttonGroupInFooter = false;

	@Element() host: HTMLHbrDrawerElement;

	@State() hasFooter = false;
	@State() hasLabel = false;
	@State() hasDescription = false;
	@State() isVisible = false;

	/** Indicates whether or not the drawer is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** Enable the native popover feature so that the drawer layers above clipping containers. @version: 2.18.46 */
	@Prop() enablePopover = false;

	/**
	 * The drawer's label as displayed in the header. You should always include a relevant label even when using
	 * `no-header`, as it is required for proper accessibility.
	 */
	@Prop() label = "";

	/** The direction from which the drawer will open. */
	@Prop() placement: "top" | "right" | "bottom" | "left" = "right";

	/**
	 * By default, the drawer slides out of its containing block (usually the viewport). To make the drawer slide out of
	 * its parent element, set this prop and add `position: relative` to the parent.
	 */
	@Prop() contained = false;

	/**
	 * Removes the header. This will also remove the default close button, so please ensure you provide an easy,
	 * accessible way for users to dismiss the drawer.
	 */
	@Prop() noHeader = false;

	/**
	 * Set or remove the overlay. Default is false.
	 */
	@Prop() overlay = false;

	/**
	 * Removed the padding in the content and footer areas.
	 */
	@Prop({ reflect: true }) noPadding = false;

	/**
	 * The drawer's width. Use the css prop --size for custom sizes.
	 */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" | "xlarge" = null;

	/**
	 * Determines whether header and footer elements' styles adapt to scroll
	 */
	@Prop({ reflect: true }) scrollAware = false;

	@Watch("open")
	handleOpenChange() {
		this.open ? this.show() : this.hide();
	}

	/** Emitted when the drawer opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the drawer opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the drawer closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the drawer closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/**
	 * Emitted when the drawer opens and the panel gains focus. Calling `event.preventDefault()` will prevent focus and
	 * allow you to set it on a different element in the drawer, such as an input or button.
	 */
	@Event({ eventName: "hbr-initial-focus" }) hbrInitialFocus: EventEmitter;

	/** Emitted when the overlay is clicked. Calling `event.preventDefault()` will prevent the drawer from closing. */
	@Event({ eventName: "hbr-overlay-dismiss" }) hbrOverlayDismiss: EventEmitter;

	connectedCallback() {
		this.handleCloseClick = this.handleCloseClick.bind(this);
		this.handleTransitionEnd = this.handleTransitionEnd.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.handleOverlayClick = this.handleOverlayClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);

		this.host.addEventListener("keydown", this.handleKeyDown, true);

		this.modal = new Modal(
			this.host,
			{
				onFocusOut: () => (this.contained ? null : this.panel?.focus()),
			},
			this.overlay,
		);
	}

	componentWillLoad() {
		this.handleSlotChange();

		// Show on init if open
		if (this.open) {
			this.show();
		}
	}

	componentDidLoad() {
		if (this.open && this.enablePopover) {
			this.drawer.showPopover();
		}
	}

	disconnectedCallback() {
		this.host.removeEventListener("keydown", this.handleKeyDown, true);
		unlockBodyScrolling(this.host);
	}

	/** Shows the drawer */
	@Method()
	async show() {
		if (this.willShow) {
			return;
		}

		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			this.open = false;
			return;
		}

		this.willShow = true;
		this.isVisible = true;
		this.open = true;

		if (this.enablePopover && this.drawer) {
			this.drawer.showPopover();
		}

		// Lock body scrolling only if the drawer isn't contained
		if (!this.contained) {
			this.modal.activate();
			if (this.overlay) lockBodyScrolling(this.host);
		}

		if (this.open) {
			if (hasPreventScroll) {
				// Wait for the next frame before setting initial focus so the dialog is technically visible
				requestAnimationFrame(() => {
					const hbrInitialFocus = this.hbrInitialFocus.emit();
					if (!hbrInitialFocus.defaultPrevented && !this.noHeader) {
						(
							this.host.shadowRoot.querySelector(
								".drawer__close",
							) as HTMLHbrButtonElement
						)?.setFocus({ preventScroll: true });
					}
				});
			} else {
				// Once Safari supports { preventScroll: true } we can remove this nasty little hack, but until then we need to
				// wait for the transition to complete before setting focus, otherwise the panel may render in a buggy way its
				// out of view initially.
				//
				// Fiddle: https://jsfiddle.net/g6buoafq/1/
				// Safari: https://bugs.webkit.org/show_bug.cgi?id=178583
				//
				this.drawer.addEventListener(
					"transitionend",
					() => {
						const hbrInitialFocus = this.hbrInitialFocus.emit();
						if (!hbrInitialFocus.defaultPrevented && !this.noHeader) {
							(
								this.host.shadowRoot.querySelector(
									".drawer__close",
								) as HTMLHbrButtonElement
							)?.setFocus({ preventScroll: true });
						}
					},
					{ once: true },
				);
			}
		}
	}

	/** Hides the drawer */
	@Method()
	async hide() {
		if (this.willHide) {
			return;
		}

		const hbrHide = this.hbrHide.emit();
		if (hbrHide.defaultPrevented) {
			this.open = true;
			return;
		}

		this.willHide = true;
		this.open = false;
		this.modal.deactivate();

		if (this.overlay) unlockBodyScrolling(this.host);
	}

	handleCloseClick() {
		this.hide();
	}

	handleKeyDown(event: KeyboardEvent) {
		if (event.key === "Escape") {
			this.hide();
		}
	}

	handleOverlayClick() {
		const hbrOverlayDismiss = this.hbrOverlayDismiss.emit();

		if (!hbrOverlayDismiss.defaultPrevented) {
			this.hide();
		}
	}

	handleSlotChange() {
		this.hasFooter = hasSlot(this.host, "footer");
		this.hasLabel = hasSlot(this.host, "label");
		this.hasDescription = hasSlot(this.host, "description");
		if (this.hasFooter) {
			if (this.host.querySelector(".hbr-css__button-group")) {
				this.buttonGroupInFooter = true;
			}
		}
	}

	handleTransitionEnd(event: TransitionEvent) {
		const target = event.target as HTMLElement;

		// Ensure we only emit one event when the target element is no longer visible
		if (
			event.propertyName === "transform" &&
			target.classList.contains("drawer__panel")
		) {
			this.isVisible = this.open;
			this.willShow = false;
			this.willHide = false;
			if (!this.open && this.enablePopover && this.drawer) {
				this.drawer.hidePopover();
			}
			this.open ? this.hbrAfterShow.emit() : this.hbrAfterHide.emit();
		}
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;

		return (
			<div
				ref={(el) => {
					this.drawer = el;
					if (this.enablePopover && this.drawer) {
						this.drawer.popover = "manual";
					}
				}}
				part="base"
				class={{
					"drawer--base": true,
					drawer: this.overlay,
					"drawer--open": this.open,
					"drawer--visible": this.isVisible,
					"drawer--top": this.placement === "top",
					"drawer--right": this.placement === "right",
					"drawer--bottom": this.placement === "bottom",
					"drawer--left": this.placement === "left",
					"drawer--contained": this.contained,
					"drawer--fixed": !this.contained,
					"drawer--has-footer": this.hasFooter,
					"drawer--no-overlay": !this.overlay,
					drawer__small: this.size === "small",
					drawer__medium: this.size === "medium",
					drawer__large: this.size === "large",
					drawer__xlarge: this.size === "xlarge",
					"drawer--no-padding": this.noPadding,
					"drawer--button-group-footer": this.buttonGroupInFooter,
				}}
				onTransitionEnd={this.handleTransitionEnd}
			>
				{this.overlay && (
					<div
						part="overlay"
						class="drawer__overlay"
						onClick={this.handleOverlayClick}
						tabIndex={-1}
					/>
				)}

				<span
					class="drawer__focus-sentinel"
					tabIndex={this.open && !this.contained ? 0 : -1}
					onFocus={() => handleStartSentinelFocus(this.panel, "drawer")}
					aria-hidden={this.open && !this.contained ? undefined : "true"}
				/>

				<div
					ref={(el) => {
						this.panel = el;
					}}
					part="panel"
					tabIndex={-1}
					class={{
						drawer__panel: true,
						drawer__small: this.size === "small",
						drawer__medium: this.size === "medium",
						drawer__large: this.size === "large",
						drawer__xlarge: this.size === "xlarge",
					}}
					role="dialog"
					aria-modal="true"
					aria-hidden={this.open ? "false" : "true"}
					aria-label={this.noHeader ? this.label : null}
					aria-labelledby={!this.noHeader ? `${this.componentId}-title` : null}
					aria-describedby={
						!this.noHeader && !this.hasLabel && this.hasDescription
							? `${this.componentId}-description`
							: null
					}
				>
					{!this.noHeader && (
						<header part="header" class="drawer__header">
							{this.hasLabel ? (
								<span
									part="title"
									class="drawer__title"
									id={`${this.componentId}-title`}
								>
									<slot name="label" onSlotchange={this.handleSlotChange} />
								</span>
							) : (
								<div part="title" class="drawer__title">
									<div
										class="drawer__heading"
										id={`${this.componentId}-title`}
										role="heading"
										aria-level="2"
									>
										<slot name="title" onSlotchange={this.handleSlotChange}>
											{/* If there's no label, use an invisible character to prevent the heading from collapsing */}
											{this.label || String.fromCharCode(65279)}
										</slot>
									</div>
									<div
										part="description"
										class="drawer__description"
										id={`${this.componentId}-description`}
										hidden={!this.hasDescription}
									>
										<slot
											name="description"
											onSlotchange={this.handleSlotChange}
										/>
									</div>
								</div>
							)}
							<hbr-button
								variant="text"
								class="drawer__close"
								part="closer"
								arialabel="close the drawer"
								exportparts="base:close-button"
								onClick={this.handleCloseClick}
								size="medium"
								data-testid="close-button"
							>
								<hbr-icon
									asset={customSystemIcons?.["x-icon"] || xIcon}
									sentiment="neutral"
									size="20px"
								/>
							</hbr-button>
						</header>
					)}

					<div
						part="body"
						class="drawer__body"
						ref={(it) => {
							this.bodyRef = it;
						}}
					>
						<slot />
					</div>

					<footer part="footer" class="drawer__footer">
						<slot name="footer" onSlotchange={this.handleSlotChange} />
					</footer>
				</div>

				<span
					class="drawer__focus-sentinel"
					tabIndex={this.open && !this.contained ? 0 : -1}
					onFocus={() => handleEndSentinelFocus(this.panel, "drawer")}
					aria-hidden={this.open && !this.contained ? undefined : "true"}
				/>

				{this.scrollAware ? <hbr-scroll-view anchor=".drawer__body" /> : null}
			</div>
		);
	}
}
